import com.hopeless.infinity.planet.*; import java.util.*;
/** RoadsTest: 0.23.0 roads (planet/Roads) against FHWA, AASHTO and MUTCD values they are built from. Saved tool. */
public class RoadsTest { static int fail = 0; static void ok(boolean c, String m) { if (!c) fail++; System.out.println((c ? "PASS " : "FAIL ") + m); }
  public static void main(String[] a) { PlanetWorld w = new PlanetWorld(1); Sites st = w.sites(); long t0 = System.nanoTime(); Roads r = w.roads(); System.out.println(r.probe());
    double sc = st.habitKm2 / Sites.US_LAND_KM2;
    double iMi = r.lenKm[0] / sc / 1.609344, aMi = r.lenKm[1] / sc / 1.609344;
    ok(Math.abs(iMi / Roads.US_INTERSTATE_MI - 1) < 0.03, String.format("Interstate %.0f mi per US land (FHWA HM-20 2023: 48,415)", iMi));
    ok(Math.abs(aMi / Roads.US_ARTERIAL_MI - 1) < 0.15, String.format("arterials %.0f mi per US land (FHWA: freeways, expressways, other principal arterials 176,104)", aMi));
    System.out.printf("collectors between places %.0f mi per US land (FHWA minor arterials and collectors, most of them in towns: 1,067,192)%n", r.lenKm[2] / sc / 1.609344);
    double cellKm2 = 4 * Math.PI * Math.pow(w.cube.R / 1000, 2) / st.habit.length, grid = 0; Rivers rv = w.terrain.rivers;
    for (int c = 0; c < st.habit.length; c++) if (rv.kind[c] != 1 && rv.kind[c] != 2 && st.habit[c] >= 0.5) grid += cellKm2 * Math.min(1, r.SECTION_K * Math.pow(st.habit[c], 3)) * 2 / Roads.MILE * 1000;
    ok(Math.abs(grid / sc / 1.609344 / Roads.US_RURAL_LOCAL_MI - 1) < 0.02, String.format("section-line roads %.0f mi per US land (FHWA rural local roads 2,015,981)", grid / sc / 1.609344));
    // laid roads: 25 of each class
    Random rnd = new Random(11); List<Integer> laid = new ArrayList<>(); for (Roads.Cls c : new Roads.Cls[]{Roads.Cls.INTERSTATE, Roads.Cls.ARTERIAL, Roads.Cls.COLLECTOR}) { int n = 0, radOk = 0, wetOk = 0, wet = 0; double mg = 0, worstR = 1e9; long ms = 0;
      while (n < 10) { Roads.Edge e = r.edges.get(rnd.nextInt(r.edges.size())); if (e.cls != c) continue; n++; laid.add(e.id); Roads.Route ro = r.route(e.id); ms += ro.ms; mg = Math.max(mg, ro.maxGrade); worstR = Math.min(worstR, ro.minRadiusM); if (ro.minRadiusM >= 0.9 * Roads.RMIN_M[c.ordinal()]) radOk++;
        for (int i = 0; i < ro.n(); i++) { double[] hw = w.terrain.heightAndWater(ro.p(i), w.cube.R); if (!Double.isNaN(hw[1]) && hw[1] > hw[0]) { wet++; if (ro.kind[i] == 1 && ro.z[i] >= hw[1] + 3.99) wetOk++; } } }
      ok(mg <= Roads.GRADE[c.ordinal()] + 1e-6, String.format("%s: steepest grade %.2f %% (limit %.0f %%) over 10 roads (%d ms each)", c, mg * 100, Roads.GRADE[c.ordinal()] * 100, ms / 10));
      ok(radOk >= 9, String.format("%s: %d of 10 roads keep every curve at 90 %% of AASHTO's minimum radius (%.0f m) or more; the tightest %.0f m", c, radOk, Roads.RMIN_M[c.ordinal()], worstR));
      ok(wet == wetOk, String.format("%s: every point over water is a bridge 4 m or more over it: %d of %d", c, wetOk, wet)); }
    // overpasses: every recorded crossing stands 7 m over the Interstate under it
    { int tried = 0, found = 0; Random rc = new Random(9); while (tried < 300 && found < 3) { Roads.Edge e = r.edges.get(rc.nextInt(r.edges.size())); if (e.cls != Roads.Cls.ARTERIAL) continue; tried++; if (!r.route(e.id).crossAt.isEmpty()) { laid.add(e.id); found++; } } System.out.println("arterials with Interstate crossings: " + found + " of " + tried + " laid"); }
    int cr = 0, crOk = 0; for (int id : laid) { Roads.Edge e = r.edges.get(id); Roads.Route ro = r.route(id);
      for (int i : ro.crossAt) { cr++; double low = Double.MAX_VALUE; for (Roads.Hit h : r.hits(ro.p(i))) if (h.edge != e.id && h.cls == Roads.Cls.INTERSTATE && Math.abs(h.off) < 10) low = Math.min(low, h.z); if (low == Double.MAX_VALUE || ro.z[i] >= low + Roads.OVERPASS_M - 0.6) crOk++; } }
    ok(cr > 0 && crOk == cr, String.format("crossings of Interstates: %d of %d stand 7 m (16.5 ft clear + deck) over the Interstate", crOk, cr));
    // unpaved share of section roads (FHWA HM-12: 56.9 % of rural local roads)
    int un = 0, all = 0; Random rs = new Random(5); for (int i = 0; i < 400000 && all < 3000; i++) { int ff = rs.nextInt(6); int x = (int) Math.round((rs.nextDouble() - 0.5) * w.cube.F / Roads.MILE) * (int) 0 + (int) Math.round(Math.round((rs.nextDouble() - 0.5) * w.cube.F / Roads.MILE) * Roads.MILE), z = (int) ((rs.nextDouble() - 0.5) * w.cube.F);
      double[] s2 = w.cube.spherePoint(ff, x + 0.5, z + 0.5); if (s2 == null) continue; double[] hw = w.terrain.heightAndWater(s2, w.cube.R); Roads.Hit h = r.section(ff, x, z, s2, hw[0], !Double.isNaN(hw[1]) && hw[1] > hw[0]); if (h == null) continue; all++; if (h.unpavedDirt || h.unpavedGravel) un++; }
    ok(all > 1000 && Math.abs(un / (double) all - Roads.UNPAVED) < 0.04, String.format("section roads unpaved %.1f %% of %d sampled (FHWA HM-12 rural local: 56.9 %%)", 100.0 * un / all, all));
    // column cost by a laid Interstate: roads on and off
    Roads.Edge ie = null; for (Roads.Edge e : r.edges) if (e.cls == Roads.Cls.INTERSTATE) { ie = e; break; } Roads.Route ro = r.route(ie.id); double[] loc = w.cube.locate(ro.p(ro.n() / 2)); int f = (int) loc[0], x0 = (int) loc[1], z0 = (int) loc[2];
    for (int dz = 0; dz < 256; dz += 4) for (int dx = 0; dx < 256; dx += 4) Column.of(w, f, x0 - 128 + dx, z0 - 128 + dz); for (int dz = 0; dz < 64; dz++) for (int dx = 0; dx < 64; dx++) Column.of(w, f, x0 + dx, z0 + dz);   // warm: every road of the measured area laid first (laying is measured on its own)
    // 0.27.3 test upkeep: one timed pass each way was noisy (+5.91 then +3.22 us on the same build); now 5 passes each way, alternating, and the difference of the medians
    double[] dOn = new double[7], dOff = new double[7]; for (int rep = 0; rep < 7; rep++) {
      long ta = System.nanoTime(); for (int dz = 0; dz < 256; dz++) for (int dx = 0; dx < 256; dx++) Column.of(w, f, x0 - 128 + dx, z0 - 128 + dz); dOn[rep] = (System.nanoTime() - ta) / 1e3 / 65536;
      Roads.on = false; ta = System.nanoTime(); for (int dz = 0; dz < 256; dz++) for (int dx = 0; dx < 256; dx++) Column.of(w, f, x0 - 128 + dx, z0 - 128 + dz); dOff[rep] = (System.nanoTime() - ta) / 1e3 / 65536; Roads.on = true; }
    java.util.Arrays.sort(dOn); java.util.Arrays.sort(dOff); double on = dOn[0], off = dOff[0];   // 0.28.6 test upkeep: the medians of 5 still swung +3.7 to +5.8 us on one build; the fastest of 7 each way (the cost with the least interference)
    ok(on - off < 5, String.format("columns by an Interstate: %.2f us with roads, %.2f us without (+%.2f)", on, off, on - off));
    // 0.23.1 interchanges: seed 1's Interstate 558 crosses Interstate 513 (a cloverleaf); random arterials until 3 diamonds
    r.route(558); { Random rd2 = new Random(21); for (int k = 0; k < 300 && Interchanges.diamonds < 3; k++) { Roads.Edge e = r.edges.get(rd2.nextInt(r.edges.size())); if (e.cls == Roads.Cls.ARTERIAL) r.route(e.id); } }
    System.out.println(Interchanges.probe()); synchronized (Interchanges.notes) { for (String nt : Interchanges.notes) System.out.println("  note: " + nt); }
    ok(Interchanges.systems >= 1 && Interchanges.diamonds >= 3, String.format("interchanges built: %d cloverleaf(s), %d diamonds", Interchanges.systems, Interchanges.diamonds));
    boolean twelve = true; synchronized (Interchanges.notes) { for (String nt : Interchanges.notes) if (nt.startsWith("cloverleaf")) twelve = false; } ok(twelve, "every cloverleaf has all 12 roads (4 C-D roads, 4 loops, 4 outer ramps)");
    double rg = 0, rr = 1e9; List<Roads.Route> rps = new ArrayList<>(r.rampRoutes()); for (Roads.Route q : rps) { rg = Math.max(rg, q.maxGrade); rr = Math.min(rr, q.minRadiusM); }
    for (Roads.Route q : rps) if (q.maxGrade > 0.0605) { int at = -1; double mg = 0; for (int i = 1; i < q.n(); i++) { double gg = Math.abs(q.z[i] - q.z[i - 1]) / (q.along[i] - q.along[i - 1]); if (gg > mg) { mg = gg; at = i; } }
      System.out.printf("  steep ramp: length %.0f, %.1f %% at %.0f m, clip %s, z %.1f -> %.1f, ends z %.1f / %.1f%n", q.along[q.n() - 1], mg * 100, q.along[at], q.clip[at], q.z[at - 1], q.z[at], q.z[0], q.z[q.n() - 1]); if (q.along[q.n() - 1] > 1000) { StringBuilder sb = new StringBuilder("    z/clip: "); for (int i = 0; i < Math.min(q.n(), 40); i++) sb.append(String.format("%.1f%s ", q.z[i], Float.isNaN(q.clip[i]) ? "" : "*")); System.out.println(sb); } }
    ok(rg <= 0.0605, String.format("ramps: steepest grade %.2f %% over %d ramps (TxDOT RDM table 15-2: 6 %% for 35-40 mph ramps)", rg * 100, rps.size()));
    { int rOk = 0, kOk = 0, endOk = 0; double worstRr = 9, worstK = 9; String wr = "", wk = ""; for (Roads.Route q : rps) { double fr = q.minRadiusM / q.rMinM; if (fr >= 0.999) rOk++; if (fr < worstRr) { worstRr = fr; wr = String.format("%.0f mph ramp %.0f m long: %.0f m (min %.0f)", q.designMph, q.along[q.n() - 1], q.minRadiusM, q.rMinM); }
        double[] ck = Profile.check(q.al.elev); double fk = Math.min(ck[0] / 0.3048 / q.kcFt, ck[1] / 0.3048 / q.ksFt); if (fk >= 0.999) kOk++; if (fk < worstK) { worstK = fk; wk = String.format("%.0f mph ramp: crest K %.0f (min %.0f), sag K %.0f (min %.0f)", q.designMph, ck[0] / 0.3048, q.kcFt, ck[1] / 0.3048, q.ksFt); } if (q.endMissCm <= 5 && q.holdMissCm <= 2) endOk++; }
      ok(rOk == rps.size(), String.format("ramps: %d of %d keep their design speed's minimum radius (TxDOT RDM 4.7.5: 30 mph 214 ft, 40 mph 444 ft); least: %s", rOk, rps.size(), wr));
      ok(kOk == rps.size(), String.format("ramps: %d of %d keep their design speed's K in the stored records (TxDOT RDM 4.8.2); least: %s", kOk, rps.size(), wk));
      ok(endOk == rps.size(), String.format("ramps: %d of %d meet their parent roads at height and grade (5 cm) and clear what they pass over (2 cm)", endOk, rps.size())); }
    int clash = 0; for (int x = 0; x < rps.size(); x++) for (int y = x + 1; y < rps.size(); y++) { Roads.Route p = rps.get(x), q = rps.get(y);
      for (int i = 0; i + 1 < p.n(); i += 1) { if (!Float.isNaN(p.clip[i]) || p.along[i] < 40 || p.along[p.n() - 1] - p.along[i] < 40) continue; double[] a1 = p.p(i); for (int j = 0; j + 1 < q.n(); j++) { if (!Float.isNaN(q.clip[j]) || q.along[j] < 40 || q.along[q.n() - 1] - q.along[j] < 40) continue; double[] b1 = q.p(j); double d = Math.acos(Math.min(1, a1[0] * b1[0] + a1[1] * b1[1] + a1[2] * b1[2])) * w.cube.R; if (d < 6 && Math.abs(p.z[i] - q.z[j]) < 5) { clash++; if (clash <= 12) System.out.printf("  clash: %s %.0f m / %s %.0f m long, at %.0f / %.0f m, z %.1f / %.1f%n", Interchanges.KIND.getOrDefault(p, "?"), p.along[p.n() - 1], Interchanges.KIND.getOrDefault(q, "?"), q.along[q.n() - 1], p.along[i], q.along[j], p.z[i], q.z[j]); break; } } } }
    ok(clash == 0, "no two free ramps meet at the same level away from their ends (closer than 6 m and 5 m in height): " + clash + " places");
    // 0.23.2 clearance under every deck round the interchanges: blocks of air over a road surface (Interstate standard: 16 ft = 4.9 m, so 5 blocks), no pier on a road
    { int minAir = 99, piers = 0, under = 0; List<double[]> bl; synchronized (Interchanges.built) { bl = new ArrayList<>(Interchanges.built); }
      for (double[] b : bl) { double[] lc = w.cube.locate(new double[]{b[0], b[1], b[2]}); int ff = (int) lc[0], xx0 = (int) lc[1], zz0 = (int) lc[2], RR = b[3] == 1 ? 120 : 60;
        for (int dz = -RR; dz <= RR; dz += 2) for (int dx = -RR; dx <= RR; dx += 2) { Column c = Column.of(w, ff, xx0 + dx, zz0 + dz); if (c.ovM == null || !(c.top == Column.Mat.ROAD_CONCRETE || c.top == Column.Mat.ASPHALT || c.top == Column.Mat.LINE_WHITE || c.top == Column.Mat.LINE_YELLOW)) continue;
          int deck = Integer.MAX_VALUE; boolean pier = false; for (int i = 0; i < c.ovM.length; i++) { int y0 = c.ovY[2 * i], y1 = c.ovY[2 * i + 1]; if (y0 > c.surfaceY && c.ovM[i] != Column.Mat.AIR) { if (y1 > y0 && y0 == c.surfaceY + 1) pier = true; deck = Math.min(deck, y0); } }
          if (pier) { piers++; continue; } if (deck == Integer.MAX_VALUE) continue; under++; minAir = Math.min(minAir, deck - c.surfaceY - 1); } }
      ok(under > 0 && minAir >= 5 && piers == 0, String.format("under bridges: %d road columns checked, least headroom %d blocks (16 ft = 4.9 m: 5 blocks), %d piers on a road", under, minAir, piers)); }
    // vertical curves: the least K on crests and sags (ft per % of grade change) against TxDOT RDM 4.8.2, 1 km from road ends (they end in towns, at town speeds) and 60 m from ramp ends (the stop at the terminal) left out; ramps against 40 mph
    { java.util.function.Function<Roads.Route, double[]> ks = rq -> { int ww = 5; double c = 1e18, sg = 1e18; for (int i = ww; i + ww < rq.n(); i++) { double endM = rq.e.cls == Roads.Cls.RAMP ? 60 : 1000; if (rq.along[i] < endM || rq.along[rq.n() - 1] - rq.along[i] < endM) continue; double d1 = rq.along[i] - rq.along[i - ww], d2 = rq.along[i + ww] - rq.along[i]; double g1 = (rq.z[i] - rq.z[i - ww]) / d1, g2 = (rq.z[i + ww] - rq.z[i]) / d2, A = (g2 - g1) * 100, L = (d1 + d2) / 2 / 0.3048; if (Math.abs(A) < 1e-4) continue; if (A < 0) c = Math.min(c, L / -A); else sg = Math.min(sg, L / A); } return new double[]{c, sg}; };
      double[][] mk = new double[5][]; for (int i = 0; i < 5; i++) mk[i] = new double[]{1e18, 1e18}; for (int id : laid) { Roads.Route rq = r.route(id); double[] q = ks.apply(rq); int c = rq.e.cls.ordinal(); if (q[0] < mk[c][0]) System.out.printf("  (least crest so far: %s %d, K %.0f, %d short curves, hold rounds %d)%n", rq.e.cls, id, q[0], rq.shortCurves, rq.holdRounds); mk[c][0] = Math.min(mk[c][0], q[0]); mk[c][1] = Math.min(mk[c][1], q[1]); }
      for (int c : new int[]{0, 1, 2}) ok(mk[c][0] >= 0.9 * Roads.KCREST_FT[c] && mk[c][1] >= 0.9 * Roads.KSAG_FT[c], String.format("%s vertical curves: least crest K %.0f (min %.0f), sag K %.0f (min %.0f) ft per %%", Roads.Cls.values()[c], mk[c][0], Roads.KCREST_FT[c], mk[c][1], Roads.KSAG_FT[c])); }
    // 0.23.2 the stored records (OpenDRIVE form): the samples are the records; plane records join end to start; spirals within the Green Book's lengths; records keep K exactly; the vertical solve's cost
    { double sMiss = 0, zMiss = 0, gp = 0, gh = 0, rgp = 0; int sp = 0, spOk = 0, kEx = 0, kAll = 0, holdBad = 0; double solveMs = 0, km = 0, iters = 0; int roads = 0; String sum = "", sWhere = "";
      for (int id : laid) { Roads.Route rq = r.route(id); Alignment al = rq.al; roads++; solveMs += rq.solveMs; km += rq.along[rq.n() - 1] / 1000; iters = Math.max(iters, rq.holdRounds); if (rq.holdMissCm > 2) holdBad++; if (sum.isEmpty()) sum = rq.e.cls + " " + id + " (" + Math.round(rq.along[rq.n() - 1] / 1000) + " km): " + al.summary();
        double hs = al.length() / (rq.n() - 1); for (int i = 0; i < rq.n(); i += 7) { double[] fe = al.eval(i * hs);   /* 0.27.6 the exact station (Roads.lay: i x hs): along[] is a float, half an ulp is 1.6 cm past 262 km (measured: the old 0.0155 m miss, Interstate 3321 at 288.6 km) */ double[] pp = rq.p(i); { double mm = Math.sqrt(Math.pow(fe[0] - pp[0], 2) + Math.pow(fe[1] - pp[1], 2) + Math.pow(fe[2] - pp[2], 2)) * w.cube.R; if (mm > sMiss) { sMiss = mm; sWhere = rq.e.cls + " " + id + " at " + Math.round(rq.along[i]) + " of " + Math.round(rq.along[rq.n() - 1]) + " m (" + al.geoAt(rq.along[i]) + ")"; } } zMiss = Math.max(zMiss, Math.abs(al.z(rq.along[i]) - rq.z[i])); }
        double[] g = al.gaps(); gp = Math.max(gp, g[0]); gh = Math.max(gh, g[1]);
        for (int k = 0; k < al.geo.size(); k++) { Alignment.Geo ge = al.geo.get(k); if (ge.type != Alignment.SPIRAL) continue; double rc = 1 / Math.max(Math.abs(ge.k0), Math.abs(ge.k1)); boolean arcNext = (ge.k0 == 0 && k + 1 < al.geo.size() && al.geo.get(k + 1).type == Alignment.ARC) || (ge.k1 == 0 && k > 0 && al.geo.get(k - 1).type == Alignment.ARC);
          if (!arcNext) continue; sp++; if (ge.len >= Math.sqrt(24 * 0.20 * rc) - 0.01 && ge.len <= Math.sqrt(24 * 1.0 * rc) + 0.01) spOk++; }
        double[] ck = Profile.check(al.elev); kAll++; int c = rq.e.cls.ordinal(); if (ck[0] / 0.3048 >= Roads.KCREST_FT[c] - 0.01 && ck[1] / 0.3048 >= Roads.KSAG_FT[c] - 0.01 && ck[2] <= Roads.GRADE[c] + 1e-6) kEx++; }
      for (Roads.Route q : rps) { double[] gg = q.al.gaps(); rgp = Math.max(rgp, gg[0]); }
      System.out.println("  e.g. " + sum);
      ok(sMiss < 0.01 && zMiss < 0.01, String.format("stored records: samples of %d roads lie on their records (largest miss %.4f m across, %.4f m in height; worst: %s)", roads, sMiss, zMiss, sWhere));
      ok(gp < 0.01 && gh < 1e-4, String.format("stored records: plane records join end to start (largest gap %.4f m, heading %.6f rad)", gp, gh));
      ok(rgp < 0.5, String.format("stored records: ramps' records join end to start within 0.5 m (largest gap %.3f m)", rgp));
      ok(sp > 0 && spOk == sp, String.format("spirals: %d of %d (before or after an arc) between the Green Book's sqrt(24 x 0.20 m x R) and sqrt(24 x 1.0 m x R)", spOk, sp));
      ok(kEx == kAll, String.format("vertical records: %d of %d roads keep their class's K and grade exactly in the records", kEx, kAll));
      ok(holdBad == 0, String.format("vertical records: %d of %d roads miss a hold (water clearance, overpass) by over 2 cm", holdBad, roads));
      ok(solveMs / km < 20, String.format("vertical solve: %.1f ms per km of road (%.0f km; most Newton steps on one road %.0f)", solveMs / km, km, iters)); }
    Roads r2 = new Roads(w); Roads.Route a1 = r.route(5), a2 = r2.route(5); boolean same = a1.n() == a2.n(); for (int i = 0; same && i < a1.n(); i += 50) same = Math.abs(a1.z[i] - a2.z[i]) < 1e-9 && a1.p(i)[0] == a2.p(i)[0];
    ok(same, "the same seed lays the same road");
    ok(r.buildMs < 15000, String.format("network built in %.1f s (in the background at server start)", r.buildMs / 1000.0));
    System.out.println("RoadsTest: " + fail + " fail"); if (fail > 0) System.exit(1); } }
